// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { 
        c = new C(address(this)); 
    }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(withdrawAmount > 0);
        vm.assume(depositAmount >= 1 ether);
        vm.assume(withdrawAmount <= type(uint256).max / 2); // avoid overflow

        // Fund the contract
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Ensure caller has sufficient balance
        uint256 balanceBefore = c.balances(caller);
        vm.assume(withdrawAmount <= balanceBefore);

        // Make the contract unable to send ETH to the caller (e.g., make caller a contract that rejects ETH)
        vm.etch(caller, address(new Rejector()).code);

        // Call CashOut
        (bool success,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", withdrawAmount));

        // In reference: if the ETH transfer fails, the whole transaction reverts => success == false
        // In mutant: no revert, balance is still decreased and no log is added => success == true
        bool isBuggy = success;

        // The general rule: if the call to CashOut does not revert, then either the transfer succeeded (which should be impossible here) or it's the buggy version
        // But we need one assertion that passes on reference (always reverts on failure) and fails on mutant (doesn't revert).
        // We'll check via revert boolean: reference always reverts, so the call returns false.
        assertTrue(!isBuggy, "The CashOut should revert when ETH transfer fails");
    }
}

contract Rejector {
    receive() external payable {
        revert("I reject ETH");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 deposit, uint256 withdrawAmount) public {
        vm.assume(caller != address(0) && caller != address(c));
        vm.deal(caller, deposit);
        vm.startPrank(caller);
        c.Deposit{value: deposit}();
        uint256 balanceBefore = c.balances(caller);
        vm.assume(withdrawAmount <= balanceBefore);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.CashOut.selector, withdrawAmount));
        vm.stopPrank();
        if (success) {
            assertTrue(c.balances(caller) == balanceBefore - withdrawAmount, "balance not decreased by full amount on success");
        } else {
            assertTrue(c.balances(caller) == balanceBefore, "balance changed on revert");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address addr, uint256 amount, uint256 depositAmount) public {
        // Ensure addr is not the contract itself (to avoid trivial failures)
        vm.assume(addr != address(c));
        vm.assume(addr != address(0));
        vm.assume(addr != address(this));

        // Bound deposit amount to be at least 1 ether to possibly deposit
        depositAmount = bound(depositAmount, 1 ether, 1000 ether);

        // Give addr some ether and deposit into the contract
        vm.deal(addr, depositAmount);
        vm.prank(addr);
        c.Deposit{value: depositAmount}();

        // Bound withdrawal amount to be in range of balance
        uint256 balance = c.balances(addr);
        vm.assume(balance > 0);
        amount = bound(amount, 1, balance);

        // Record state before CashOut
        uint256 preBal = addr.balance;
        uint256 preContractBal = c.balances(addr);

        // Make the recipient address unable to receive ether (e.g., address(this) but it already can; use a contract that rejects)
        // For the test to trigger revert, we need the address to revert on receive.
        // We can use a pre-funded address that we don't care about, and set it to a contract that rejects.
        // However, simpler: the original call fails when the recipient is a contract with no receive() or fallback.
        // Here we use address(this) which has a receive() (the test contract), so it will succeed. To make it fail,
        // we can prank a different address that is the msg.sender but have the recipient be address(this) with no receive?
        // Actually, to make the call fail, we need the recipient (msg.sender) to revert on receive. We'll simulate by
        // having the recipient be a contract that rejects, but we can't easily create one here without a separate contract.
        // Instead, we note that the invariant is about the state preserving on revert. So we'll just call CashOut with
        // some amount and check the invariant: the total (addr.balance + c.balances(addr)) does not increase after a call.

        // Actually, the bug is that on revert the balance is still decreased, so the sum addr.balance + c.balances(addr) should remain constant on a revert.
        // In the buggy version, if the call fails, the balance decreases but ETH is not sent, so sum decreases.
        // In the reference, sum stays same.
        // So we check that the sum does not decrease after the call (i.e., it stays same or increases only from other actions).

        vm.prank(addr);
        // We need the call to possibly fail. To ensure it fails, we can set the recipient address to be a contract that cannot receive.
        // Simplify: we'll just call CashOut normally; the test will revert sometimes, and we catch it.
        try c.CashOut(amount) {
            // If it succeeds, the balance should decrease as per rules. But we focus on the sum invariant.
            // Actually the property is simpler: after any CashOut call (success or revert), sum does not increase.
        } catch {
            // on revert, check that sum did not increase
        }

        uint256 postBal = addr.balance;
        uint256 postContractBal = c.balances(addr);

        // The sum should not have increased (strictly). This holds for reference (on revert sum unchanged; on success sum unchanged because ETH moves).
        // Bug: on revert, sum decreases because balance is decremented but ETH not sent.
        assertTrue(preBal + preContractBal >= postBal + postContractBal, "Sum increased");
    }
}

