pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 deposit, uint256 withdrawal) public {
        // Bound inputs to reasonable ranges
        vm.assume(caller != address(0));
        deposit = bound(deposit, 1 ether, 1000 ether); // ensure deposit meets min deposit
        withdrawal = bound(withdrawal, 0, deposit); // withdrawal <= deposit

        // Fund caller and deposit
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Deposit{value: deposit}();

        // Record the sum of all balances in the contract via its public getter
        // Since we can't iterate over all addresses, we track a single caller's balance
        // The rule: after CashOut, the caller's balance in the contract is either unchanged (if revert) or decreased by withdrawal (if success)
        uint256 balanceBefore = c.balances(caller);

        // Call CashOut
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", withdrawal));

        // Read balance after
        uint256 balanceAfter = c.balances(caller);

        // General rule: balance is either unchanged (if call reverted) or decreased by exactly withdrawal (if call succeeded)
        assertTrue(
            (!success && balanceAfter == balanceBefore) ||
            (success && balanceAfter == balanceBefore - withdrawal)
        );
    }
}

