        if (deposit >= 1 ether) {
            (bool ok,) = address(c).call{value: deposit}("");
            // Then call Deposit explicitly
            c.Deposit{value: deposit}();
        }

        // Now call CashOut
        vm.prank(caller);
        (bool cashOutOk,) = address(c).call(abi.encodeWithSelector(c.CashOut.selector, withdraw));
