contract InvMutTest is Test {
    C c;

    function setUp() public { 
        c = new C(address(this)); 
    }

    function testFuzz_property(address addr, uint256 depositAmt, uint256 cashOutAmt) public {
        // Bound deposit amount to reasonable values and ensure enough ETH
        vm.assume(addr != address(0));
        uint256 deposit = bound(depositAmt, 1 ether, 100 ether);
        vm.deal(addr, deposit);

        // Deposit
        vm.prank(addr);
        c.Deposit{value: deposit}();

        // Track state before CashOut
        uint256 sumBalBefore = c.balances(addr);
        uint256 contractBalanceBefore = address(c).balance;

        // Bound cashOutAmt to avoid revert on reference (must be <= balance)
        vm.assume(cashOutAmt <= sumBalBefore);

        // Call CashOut
        vm.prank(addr);
