pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    mapping(address => uint) public deposits;
    mapping(address => uint) public withdrawals;

    function setUp() public { 
        c = new C(address(this)); 
    }

    function testFuzz_property(address k, uint256 depositVal, uint256 withdrawVal) public {
        // Bound inputs to avoid trivial overflow/underflow
        depositVal = bound(depositVal, 1 ether, 100 ether);  // meets MinDeposit
        withdrawVal = bound(withdrawVal, 0, depositVal);     // cannot withdraw more than deposited
        vm.assume(k != address(0));

        // Simulate a deposit by k
        vm.deal(k, depositVal);
        vm.prank(k);
        c.Deposit{value: depositVal}();
        deposits[k] += depositVal;

        // Withdraw exactly withdrawVal
        vm.prank(k);
        (bool success,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", withdrawVal));
        if (success) {
            withdrawals[k] += withdrawVal;
        }

        // General rule: For any address k, its balance should not exceed net deposited
        uint256 netDeposit = deposits[k] - withdrawals[k];
        assertTrue(c.balances(k) <= netDeposit);
    }
}

