pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user1, uint256 depositAmt, uint256 cashoutAmt) public {
        vm.assume(user1 != address(0));
        // Bound depositAmt to avoid overflow and keep it >= MinDeposit
        depositAmt = bound(depositAmt, 1 ether, 1000 ether);
        cashoutAmt = bound(cashoutAmt, 0, address(c).balance + c.balances(user1));

        // Record initial state
        uint256 initContractBal = address(c).balance;
        uint256 initUserBal = c.balances(user1);
        uint256 initTotal = initContractBal + initUserBal;

        // Deposit
        vm.deal(user1, depositAmt);
        vm.prank(user1);
        c.Deposit{value: depositAmt}();

        // Cash out
        vm.prank(user1);
        (bool success, ) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", cashoutAmt));

        // Measure final state
        uint256 finalContractBal = address(c).balance;
        uint256 finalUserBal = c.balances(user1);
        uint256 finalTotal = finalContractBal + finalUserBal;

        // The rule: total ether + balances should be conserved (amounts only move between user and contract)
        // Since deposit adds to contract and user balance, cashout reduces user balance and may send ether.
        // The only external ether flow is the deposit (user -> contract) and cashout (contract -> user).
        // The sum of user's balance and contract's balance should equal the initial sum + deposit - (amount sent on successful cashout).
        // Actually, after deposit, contract balance increases, user balance increases. After cashout, if successful, contract balance decreases by cashoutAmt, user balance decreases by cashoutAmt.
        // So the sum should equal initTotal + depositAmt - (if success ? cashoutAmt : 0).
        if (success) {
            assertTrue(finalTotal == initTotal + depositAmt - cashoutAmt, "Invariant violated on successful cashout");
        } else {
            assertTrue(finalTotal == initTotal + depositAmt, "Invariant violated on failed cashout");
        }
    }
}

