import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(user != address(0));
        vm.assume(user != address(this));
        // Bound deposit to be at least 1 ether to be accepted
        uint256 deposit = bound(depositAmount, 1 ether, 1000 ether);
        // Fund the test contract to send ETH to user for deposit
        deal(address(this), deposit);
        vm.deal(user, deposit);

        // Deposit from user
        vm.prank(user);
        c.Deposit{value: deposit}();

        // Get balance before cashout
        uint256 balanceBefore = c.balances(user);

        // Bound withdraw amount to ensure it's positive but may exceed balance
        uint256 withdraw = bound(withdrawAmount, 0, balanceBefore + 1 ether);

        // Record if cashout reverts
        bool revertCaught = false;
        try c.CashOut(withdraw) {
            // If successful, check that balance decreased appropriately
            uint256 balanceAfter = c.balances(user);
            assertTrue(balanceAfter <= balanceBefore, "Balance should never increase after cashout");
            if (withdraw <= balanceBefore) {
                assertTrue(balanceAfter == balanceBefore - withdraw, "Balance should decrease by exact amount if sufficient");
            }
        } catch {
            revertCaught = true;
            // If withdrew more than balance, revert is expected in reference
            if (withdraw > balanceBefore) {
                assertTrue(true, "Correctly reverted for insufficient balance");
            } else {
                // Should not revert for valid withdraw
                assertTrue(false, "Unexpected revert when withdraw <= balance");
            }
        }

        // General rule: balance after cashout should never be greater than balance before
        // This will fail on buggy version where condition removed
        // (tested via revert behavior: buggy version will succeed even when withdraw > balance)
        if (!revertCaught && withdraw > balanceBefore) {
            // This path should only happen in buggy version
            assertTrue(false, "Bug: CashOut succeeded despite insufficient balance");
        }
    }
}

