        require(okLen);
        // The return is a tuple (address, string, uint256, uint256). We cannot easily decode without interface, but we can get the length by reading the array's length which is at slot 0 of the Log contract.
        // Actually, public array getter History(uint256) returns struct. The length is stored at slot 0.
        uint256 historyLen;
        assembly {
            historyLen := sload(logAddr.slot, 0)
        }
        revert();
    }
